        int result = 0;
        int term = n;
        int operation = 0;

        for (int value = n - 1; value >= 1; value--) {
            switch (operation) {
                case 0:
                    term *= value;
                    break;
                case 1:
                    // Truncation preserves the sign of a subtracted quotient.
                    term /= value;
